def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    seen = {}
    order = []
    for w in words:
        key = w.lower()
        if key not in seen:
            seen[key] = w
            order.append(key)
        seen[key] = seen.get(key, (w, 0))
        # use a dict to track (canonical_form, count)

    # Rebuild properly
    canonical = {}
    counts = {}
    for w in words:
        key = w.lower()
        if key not in canonical:
            canonical[key] = w
            counts[key] = 0
        counts[key] += 1

    # Build sorted list: by count desc, then by first appearance order asc
    indexed = [(key, counts[key], idx) for idx, key in enumerate(order)]
    indexed.sort(key=lambda x: (-x[1], x[2]))

    return [(canonical[key], cnt) for key, cnt, _ in indexed[:k]]
