def parse_jsonl_metrics(lines: list[str]) -> dict:
    result = {"invalid": 0}
    per_service = {}
    invalid = 0

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue

        try:
            record = json.loads(stripped)
        except (json.JSONDecodeError, ValueError):
            invalid += 1
            continue

        if not isinstance(record, dict):
            invalid += 1
            continue

        service = record.get("service")
        latency = record.get("latency_ms")
        status = record.get("status")

        if not isinstance(service, str):
            invalid += 1
            continue
        if not isinstance(latency, (int, float)) or isinstance(latency, bool):
            invalid += 1
            continue
        if not isinstance(status, (int, float)) or isinstance(status, bool):
            invalid += 1
            continue

        latency = float(latency)
        status = int(status)

        if service not in per_service:
            per_service[service] = []
        per_service[service].append((status, latency))

    for service in sorted(per_service.keys()):
        samples = per_service[service]
        n = len(samples)
        ok_count = sum(1 for s, _ in samples if 200 <= s < 300)
        ok_rate = ok_count / n if n > 0 else 0.0

        latencies = sorted(l for _, l in samples)
        if n == 0:
            p95 = None
        else:
            idx = math.ceil(0.95 * n) - 1
            p95 = latencies[idx]

        result[service] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95,
        }

    result["invalid"] = invalid
    return result
