class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {cycle}")


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    for n in nodes:
        if not isinstance(n, str) or n == "":
            raise ValueError("Invalid node name")

    seen = set()
    for a, b in edges:
        if a not in node_set:
            raise ValueError(f"Unknown node: {a}")
        if b not in node_set:
            raise ValueError(f"Unknown node: {b}")

    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for a, b in edges:
        if b not in adj[a]:
            adj[a].add(b)
            in_degree[b] += 1

    import heapq
    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        # Find cycle
        remaining = set(nodes) - set(result)
        # Build subgraph
        r_adj = {n: [] for n in remaining}
        for a, b in edges:
            if a in remaining and b in remaining:
                r_adj[a].append(b)
        # DFS to find cycle
        visited = {}
        cycle_path = []

        def dfs(u, stack):
            visited[u] = 1  # gray
            stack.append(u)
            for v in r_adj[u]:
                if v not in visited:
                    dfs(v, stack)
                elif visited[v] == 1:
                    # Found cycle
                    idx = stack.index(v)
                    cycle_path.extend(stack[idx:])
                    cycle_path.append(v)
                    raise StopIteration
            stack.pop()
            visited[u] = 2  # black

        for n in remaining:
            if n not in visited:
                try:
                    dfs(n, [])
                except StopIteration:
                    break
        raise CycleError(cycle_path)

    return result
