def apply_patch_ops(document: dict, operations) -> dict:
    import copy

    new_doc = copy.deepcopy(document)

    if not isinstance(operations, (list, tuple)):
        raise TypeError("operations must be a list or tuple of (op, path, value) tuples")

    for index, item in enumerate(operations):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError(
                f"operations[{index}] must be a (op, path, value) triple, got: {item!r}"
            )
        op, path, value = item
        if not isinstance(op, str):
            raise ValueError(
                f"operations[{index}] op must be a string, got: {op!r}"
            )

        # Parse the path into a list of keys
        if not isinstance(path, str) or path == "":
            raise ValueError(
                f"operations[{index}] path must be a non-empty string, got: {path!r}"
            )
        keys = path.split(".")
        if any(k == "" for k in keys):
            raise ValueError(
                f"operations[{index}] path contains empty segment: {path!r}"
            )

        if op == "set":
            _set_at(new_doc, keys, value)

        elif op == "delete":
            _delete_at(new_doc, keys)

        elif op == "increment":
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError(
                    f"operations[{index}] 'increment' value must be int or float, got: {value!r}"
                )
            _increment_at(new_doc, keys, value)

        else:
            raise ValueError(
                f"operations[{index}] unsupported op: {op!r}"
            )

    return new_doc


def _set_at(root, keys, value):
    cursor = root
    for key in keys[:-1]:
        nxt = cursor.get(key)
        if not isinstance(nxt, dict):
            nxt = {}
            cursor[key] = nxt
        cursor = nxt
    cursor[keys[-1]] = value


def _delete_at(root, keys):
    if len(keys) == 1:
        if keys[0] in root and isinstance(root, dict):
            del root[keys[0]]
        return

    cursor = root
    for key in keys[:-1]:
        nxt = cursor.get(key)
        if not isinstance(nxt, dict):
            return
        cursor = nxt
    if isinstance(cursor, dict) and keys[-1] in cursor:
        del cursor[keys[-1]]


def _increment_at(root, keys, delta):
    cursor = root
    for key in keys[:-1]:
        nxt = cursor.get(key)
        if not isinstance(nxt, dict):
            raise KeyError(f"path '{'.'.join(keys)}' does not exist for increment")
        cursor = nxt
    current = cursor.get(keys[-1])
    if current is None:
        raise KeyError(f"path '{'.'.join(keys)}' does not exist for increment")
    if isinstance(current, bool) or not isinstance(current, (int, float)):
        raise TypeError(
            f"path '{'.'.join(keys)}' value must be int or float for increment, got: {type(current).__name__}"
        )
    cursor[keys[-1]] = current + delta
