import asyncio
from typing import List, Tuple, Any


async def run_with_deadline(
    coros: List[Any],
    limit: int,
    timeout: float,
) -> List[Tuple[str, Any]]:
    if not coros:
        return []

    n = len(coros)
    results: List[Tuple[str, Any]] = [None] * n  # type: ignore
    deadline_task: asyncio.Task = asyncio.create_task(asyncio.sleep(timeout))

    pending: set = set()
    for i, coro in enumerate(coros):
        t = asyncio.create_task(_runner(coro))
        t._idx = i  # type: ignore[attr-defined]
        pending.add(t)

    try:
        while pending:
            done, pending = await asyncio.wait(
                pending,
                return_when=asyncio.FIRST_COMPLETED,
            )

            # Process completed tasks first
            for d in done:
                idx: int = d._idx  # type: ignore[attr-defined]
                if d.cancelled():
                    results[idx] = ("cancelled", None)
                else:
                    exc = d.exception()
                    if exc is None:
                        results[idx] = ("ok", d.result())
                    else:
                        results[idx] = ("error", exc)

            # Check if overall timeout has been hit
            if deadline_task.done():
                # Cancel everything still pending
                for p in pending:
                    p.cancel()
                if pending:
                    await asyncio.wait(pending, return_when=asyncio.ALL_COMPLETED)
                break

            # Schedule new tasks to keep up to `limit` running
            slots = limit - len(pending)
            next_idx = len(done) + _scheduled_count(done)
            for i in range(next_idx, min(n, next_idx + slots)):
                t = asyncio.create_task(_runner(coros[i]))
                t._idx = i  # type: ignore[attr-defined]
                pending.add(t)
    finally:
        if not deadline_task.done():
            deadline_task.cancel()
            try:
                await deadline_task
            except (asyncio.CancelledError, Exception):
                pass
        # Defensive: cancel any remaining pending tasks
        if pending:
            for p in pending:
                p.cancel()
            await asyncio.wait(pending, return_when=asyncio.ALL_COMPLETED)

    # If some results are still missing (shouldn't happen, but safety), mark cancelled
    for i, r in enumerate(results):
        if r is None:
            results[i] = ("cancelled", None)

    return results


_scheduled_count = lambda done: 0  # placeholder to avoid redefinition order issues


def _scheduled_count(done):
    return sum(1 for d in done if getattr(d, "_scheduled", False))


async def _runner(coro):
    return await coro
