import threading
from concurrent.futures import Future
from typing import Callable, Any, Dict, TypeVar

T = TypeVar("T")


class IdempotentEventProcessor:
    def __init__(self, apply: Callable[[Any], Any]):
        self._apply = apply
        self._lock = threading.Lock()
        self._futures: Dict[Any, Future] = {}
        self._results: Dict[Any, Any] = {}

    def process(self, event_id: Any, payload: Any) -> None:
        with self._lock:
            if event_id in self._results:
                return
            if event_id in self._futures:
                future = self._futures[event_id]
            else:
                future = Future()
                self._futures[event_id] = future
                thread = threading.Thread(
                    target=self._run, args=(event_id, payload, future), daemon=True
                )
                thread.start()
        future.result()

    def _run(self, event_id: Any, payload: Any, future: Future) -> None:
        try:
            result = self._apply(payload)
        except BaseException as exc:
            with self._lock:
                self._futures.pop(event_id, None)
            future.set_exception(exc)
            return
        with self._lock:
            self._futures.pop(event_id, None)
            self._results[event_id] = result
        future.set_result(result)

    def result(self, event_id: Any) -> Any:
        with self._lock:
            if event_id in self._results:
                return self._results[event_id]
        raise KeyError(event_id)
