import threading


class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._q = []
        self._cap = capacity
        self._cond = threading.Condition()
        self._closed = False
        self._closed_event = threading.Event()

    def put(self, item):
        with self._cond:
            while len(self._q) >= self._cap and not self._closed:
                self._cond.wait()
            if self._closed:
                raise RuntimeError("queue is closed")
            self._q.append(item)
            self._cond.notify()

    def get(self):
        with self._cond:
            while len(self._q) == 0 and not self._closed:
                self._cond.wait()
            if self._q:
                item = self._q.pop(0)
                self._cond.notify()
                return item
            if self._closed:
                raise RuntimeError("queue is closed and empty")
            raise RuntimeError("queue is closed and empty")

    def close(self):
        with self._cond:
            if self._closed:
                return
            self._closed = True
        self._closed_event.set()
        with self._cond:
            self._cond.notify_all()

    def is_closed(self):
        return self._closed_event.is_set()
