import threading
import copy


class VersionedStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._data = {}

    def read(self, key):
        with self._lock:
            if key not in self._data:
                return None
            version, value = self._data[key]
            return copy.deepcopy(value), version

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            if key not in self._data:
                if expected_version != 0:
                    return False
                self._data[key] = (1, copy.deepcopy(value))
                return True
            current_version, _ = self._data[key]
            if current_version != expected_version:
                return False
            self._data[key] = (current_version + 1, copy.deepcopy(value))
            return True

    def delete(self, key, expected_version):
        with self._lock:
            if key not in self._data:
                return False
            current_version, _ = self._data[key]
            if current_version != expected_version:
                return False
            del self._data[key]
            return True

    def snapshot(self):
        with self._lock:
            result = {}
            for key, (version, value) in self._data.items():
                result[key] = (version, copy.deepcopy(value))
            return result
