class ReplicatedLog:
    def __init__(self):
        # term 0 是未初始化的哨兵 term，防止 index 0 处的 prev_term 比较出错
        self._log = [(0, None)]      # (term, command)，index 从 1 开始
        self._term = 0
        self._commit_index = 0
        self._last_applied = 0

    def current_index(self) -> int:
        return len(self._log) - 1

    def current_term(self) -> int:
        return self._term

    def append(self, command) -> int:
        self._log.append((self._term, command))
        return self.current_index()

    def _match(self, prev_index: int, prev_term: int) -> bool:
        if prev_index == 0:
            return True
        if prev_index >= len(self._log):
            return False
        return self._log[prev_index][0] == prev_term

    def receive_append(
        self, term: int, prev_index: int, prev_term: int,
        entries: list, leader_commit: int
    ) -> bool:
        if term < self._term:
            return False
        if term > self._term:
            self._term = term
        if not self._match(prev_index, prev_term):
            return False
        # 从 prev_index+1 开始，幂等检查：entries[0] 若已存在且 term 一致则截断
        idx = prev_index + 1
        i = 0
        while i < len(entries) and (idx + i) < len(self._log):
            existing_term, _ = self._log[idx + i]
            if existing_term != term:
                # 真正的冲突：截断此处之后的所有内容
                self._log = self._log[: idx + i]
                break
            i += 1
        else:
            # 全部前缀一致，没有冲突；剩余 entries 应追加
            # 但如果 entries 数量比 log 已有超出，超出部分直接追加
            self._log = self._log[: idx + i]
        # 追加剩余 entries
        for j in range(i, len(entries)):
            self._log.append((term, entries[j]))
        # 更新 commit，不能超过本地最后一项
        if leader_commit > self.current_index():
            leader_commit = self.current_index()
        if leader_commit > self._commit_index:
            self._commit_index = leader_commit
        return True

    def commit_to(self, index: int) -> None:
        if index > self.current_index():
            index = self.current_index()
        if index > self._commit_index:
            self._commit_index = index
        # committed 不能回退；已 apply 的 index 也不得回退（由 apply_committed 保证）

    def apply_committed(self) -> list:
        applied = []
        while self._last_applied < self._commit_index:
            self._last_applied += 1
            applied.append(self._log[self._last_applied][1])
        return applied


# 5 条最能暴露错误的测试用例：
# 1. term 回退防护：先以 term=5 receive_append，再以 term=3 发送，
#    receive_append 应返回 False 且本地 term 不被降低。
# 2. prev_index 越界 / prev_term 不匹配：leader 用 prev_index=100 调用，
#    应返回 False 且不修改任何状态（log、commit_index 均不变）。
# 3. 冲突 suffix 覆盖：本地 log 末尾是 (5, 'x')，leader 携带 term=6、entries=['y']、
#    prev_index 指向前一条，匹配后旧 'x' 必须被新 term 的内容覆盖。
# 4. 重复接收幂等：同一批 (term, prev_index, prev_term, entries) 连续调用两次，
#    log 长度不应翻倍，apply_committed 也只返回一次结果。
# 5. commit 边界 + apply 单调性：leader_commit 大于本地最后一项时必须截断；
#    且当已 apply 到 index=5 后，新一轮 receive_append 使 commit_index 暂时回退
#    到 3（不直接发生，但通过手动调用 commit_to 模拟），_last_applied 不得回退，
#    apply_committed 不重复返回已 apply 的命令。
