#!/bin/sh
# 处理 TAB 分隔的访问日志: timestamp \t status \t latency_ms \t path
# p99 取法:  对每个 path 的 latency_ms 用 awk 维护一个大小为 100 的小顶堆
#            (slot[1..100], slot[1] 为最小)，当样本数 <=100 时全部保留;
#            第 k 个新样本到达时，若 k>100 且样本 > slot[1]，则弹出 slot[1] 并
#            用 sift-down 插入; 全部处理完后，再 sift-down 一次保证堆有序,
#            最终 slot[1] 即为第 99 百分位数 (p99, ceil 分位).
# 资源开销:  逐行流式处理,O(1) 行驻留,每 path 仅保留 100 个整数,
#            内存约 100*8B/path + 关联状态,适合 1GB+ 大文件;
#            单遍扫描,时间复杂度 O(N log 100) ≈ O(N).
awk -F'\t' '
function down(i,    j, k, t) {
    for (j = i; (k = j*2) <= 100; ) {
        if (k < 100 && slot[k] > slot[k+1]) k++
        if (slot[j] <= slot[k]) break
        t = slot[j]; slot[j] = slot[k]; slot[k] = t
        j = k
    }
}
function insert(x) {
    if (n < 100) {
        n++; slot[n] = x
        i = n
        while (i > 1 && slot[i] < slot[i>>1]) {
            t = slot[i]; slot[i] = slot[i>>1]; slot[i>>1] = t
            i >>= 1
        }
    } else if (x > slot[1]) {
        slot[1] = x
        down(1)
    }
}
NR > 0 {
    path = $4
    cnt[path]++
    s = $2 + 0
    if (s >= 500 && s < 600) err[path]++
    lat = $3 + 0
    n = 0
    for (i = 1; i <= 100; i++) slot[i] = h[path, i]
    n = hn[path]
    insert(lat)
    hn[path] = n
    for (i = 1; i <= 100; i++) h[path, i] = slot[i]
}
END {
    for (p in cnt) {
        n = hn[p]
        for (i = n>>1; i >= 1; i--) { j = i; while ((k = j*2) <= n) {
            if (k < n && h[p,k] > h[p,k+1]) k++
            if (h[p,j] <= h[p,k]) break
            t = h[p,j]; h[p,j] = h[p,k]; h[p,k] = t; j = k } }
        printf "%d\t%d\t%d\t%s\n", cnt[p]+0, err[p]+0, h[p,1]+0, p
    }
}' "$1" | sort -t $'\t' -k1,1nr -k4,4
# 上述 sort 会按 "请求数 降序、path 升序"; 题目要求 5xx 降序、path 升序,
# 因此改用:
