import math


def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    begin, end = -1.0, 1.0
    step = 0.0001
    x = begin
    while x <= end:
        if abs(poly(xs, x)) < 1e-6:
            return x
        x += step
    return None
